# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">EL SANATLARI (الْفُنُونُ الْيَدَوِيَّةُ / الْأَعْمَالُ الْيَدَوِيَّةُ)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Geleneksel Türk-İslam Sanatları</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">الْخَطُّ الْعَرَبِيُّ / حُسْنُ الْخَطِّ (Hüsn-i Hat / Güzel Yazı)</text>\n  <text x="180" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">فَنُّ التَّذْهِيبِ (Tezhip / Altınla Süsleme Sanatı)</text>\n  <text x="180" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">فَنُّ الْأَبْرُو / الرَّسْمُ عَلَى الْمَاءِ (Ebru Sanatı)</text>\n  <text x="180" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">فَنُّ الْخَزَفِ / الصِّينِيّ (Çini ve Seramik Sanatı)</text>\n  <text x="180" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">النَّقْشُ عَلَى الْخَشَبِ وَالنُّحَاسِ (Ahşap ve Bakır İşlemeciliği)</text>\n  <text x="180" y="224" text-anchor="middle" font-size="11" fill="#334155">حِيَاكَةُ السَّجَّادِ (Halı ve Kilim Dokumacılığı)</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Sanatçılar ve Niteleme Cümleleri</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">خَطَّاطٌ (Hattat) · مُذَهِّبٌ (Müzehhip) · فَنَّانٌ (Sanatçı)</text>\n  <text x="520" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">اَلْأَعْمَالُ الْيَدَوِيَّةُ مُمْتِعَةٌ (El sanatları eğlencelidir)</text>\n  <text x="520" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">اَلْخَطُّ الْعَرَبِيُّ سَهْلٌ وَجَمِيلٌ (Arap hattı kolay ve güzeldir)</text>\n  <text x="520" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">فَنُّ الْأَبْرُو رَائِعٌ جِدًّا (Ebru sanatı çok harikadır)</text>\n  <text x="520" y="202" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">مَنْ لَا يَعْمَلُ لَا يُنْتِجُ (Çalışmayan üretmez)</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" fill="#166534">اَلْعَمَلُ خَيْرٌ مِنَ التَّسَوُّلِ (Çalışmak dilenmekten hayırlıdır)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">EL SANATLARI SERGİSİ (مَعْرِضُ الْفُنُونِ الْيَدَوِيَّةِ) VE ATÖLYE</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Sergi ve Kurs Diyalog Kalıpları</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">أَيْنَ يُقَامُ مَعْرِضُ الْفُنُونِ؟ (Sanat sergisi nerede kuruluyor?)</text>\n  <text x="180" y="120" text-anchor="middle" font-size="11" fill="#713f12">يُقَامُ فِي الْمَرْكَزِ الثَّقَافِيِّ (Kültür merkezinde kuruluyor)</text>\n  <text x="180" y="146" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">أَيَّ فَنٍّ تُفَضِّلُ؟ (Hangi sanatı tercih edersin?)</text>\n  <text x="180" y="170" text-anchor="middle" font-size="11" fill="#713f12">أُفَضِّلُ فَنَّ التَّذْهِيبِ وَالْأَبْرُو (Tezhip ve ebruyu tercih ederim)</text>\n  <text x="180" y="196" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">أَشْتَرِكُ فِي دَوْرَةِ الْخَطِّ (Hat kursuna katılıyorum)</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11" fill="#713f12">لَوْحَةٌ فَنِّيَّةٌ (Sanat tablosu / levhası) · وَرْشَةٌ (Atölye)</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Uygulama Yönergeleri ve Malzemeler</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">فُرْشَاةٌ (Fırça) · أَلْوَانٌ (Boyalar) · وَرَقٌ (Kâğıt)</text>\n  <text x="520" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">قَلَمُ الْقَصَبِ (Kamış kalem) · حِبْرٌ (Mürekkep)</text>\n  <text x="520" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">1. خُذِ الْفُرْشَاةَ وَالْأَلْوَانَ (Fırçayı ve boyaları al)</text>\n  <text x="520" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">2. اُرْسُمْ عَلَى الْمَاءِ بِدِقَّةٍ (Su üzerine dikkatlice çiz)</text>\n  <text x="520" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">3. ضَعِ الْوَرَقَةَ ثُمَّ ارْفَعْهَا (Kâğıdı koy, sonra kaldır)</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" fill="#475569">هَذِهِ اللَّوْحَةُ مِنْ صُنْعِ يَدِي (Bu tablo kendi el emeğimdir)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KÜLTÜR VE SANAT (الثَّقَافَةُ وَالفَنُّ) — GENEL BAKIŞ</text>\n  <rect x="20" y="45" width="210" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#be123c">1. Edebiyat ve Fuar</text>\n  <text x="125" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">مَعْرِضُ الْكِتَابِ (Kitap Fuarı)</text>\n  <text x="125" y="122" text-anchor="middle" font-size="11" fill="#881337">رِوَايَةٌ (Roman) · قِصَّةٌ (Hikâye)</text>\n  <text x="125" y="148" text-anchor="middle" font-size="11" fill="#881337">شِعْرٌ (Şiir) · كَاتِبٌ (Yazar)</text>\n  <text x="125" y="174" text-anchor="middle" font-size="11" fill="#881337">إِلَى أَيْنَ / مَعَ مَنْ / مَتَى</text>\n  <text x="125" y="202" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">تَسْقُطُ أَوْرَاقُ الْأَشْجَارِ</text>\n  <text x="125" y="222" text-anchor="middle" font-size="10" fill="#881337">(Ağaçların yaprakları dökülür)</text>\n\n  <rect x="245" y="45" width="210" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#0e7490">2. Sinema ve Tiyatro</text>\n  <text x="350" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">السِّينَمَا وَالْمَسْرَحُ</text>\n  <text x="350" y="122" text-anchor="middle" font-size="11" fill="#164e63">فِيلْمٌ وَثَائِقِيٌّ (Belgesel film)</text>\n  <text x="350" y="148" text-anchor="middle" font-size="11" fill="#164e63">مَسْرَحِيَّةٌ تَارِيخِيَّةٌ (Tarihî oyun)</text>\n  <text x="350" y="174" text-anchor="middle" font-size="11" fill="#164e63">مُمَثِّلٌ (Oyuncu) · تَذْكِرَةٌ (Bilet)</text>\n  <text x="350" y="202" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">قَبْلَ · وَ · ثُمَّ · بَعْدَ</text>\n  <text x="350" y="222" text-anchor="middle" font-size="10" fill="#164e63">(Olay sıralama bağlaçları)</text>\n\n  <rect x="470" y="45" width="210" height="195" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">3. El Sanatları</text>\n  <text x="575" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">الْفُنُونُ الْيَدَوِيَّةُ</text>\n  <text x="575" y="122" text-anchor="middle" font-size="11" fill="#14532d">الْخَطُّ · التَّذْهِيبُ · الْأَبْرُو · الْخَزَفُ</text>\n  <text x="575" y="148" text-anchor="middle" font-size="11" fill="#14532d">الأَعْمَالُ الْيَدَوِيَّةُ مُمْتِعَةٌ</text>\n  <text x="575" y="174" text-anchor="middle" font-size="11" fill="#14532d">الْخَطُّ الْعَرَبِيُّ سَهْلٌ</text>\n  <text x="575" y="202" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">مَنْ لَا يَعْمَلُ لَا يُنْتِجُ</text>\n  <text x="575" y="222" text-anchor="middle" font-size="10" fill="#14532d">(Çalışmayan üretmez)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
